import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        StringTokenizer st = new StringTokenizer(new String(System.in.readAllBytes()));
        int n = Integer.parseInt(st.nextToken()), best = -1;
        String bestId = "";
        for (int i = 0; i < n; i++) {
            String id = st.nextToken();
            int v = Integer.parseInt(st.nextToken());  // leading zeros are fine
            if (v > best) { best = v; bestId = id; }
        }
        System.out.println(bestId);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<26)
	sc.Split(bufio.ScanWords)
	next := func() string { sc.Scan(); return sc.Text() }
	n, _ := strconv.Atoi(next())
	best, bestID := -1, ""
	for i := 0; i < n; i++ {
		id := next()
		v, _ := strconv.Atoi(next()) // leading zeros are fine
		if v > best {
			best, bestID = v, id
		}
	}
	fmt.Println(bestID)
}
